/** Build the horizontal wordmark SVG string for a given icon/text color. */
export function horizontalSvg(icon: string, text: string): string {
  const textPaths = HORIZONTAL_TEXT_PATHS.map(
    (d) => `<path fill="${text}" d="${d}"/>`
  ).join("");
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" width="251" height="77" viewBox="0 0 251 77" fill="none">` +
    textPaths +
    `<path fill="${icon}" d="${HORIZONTAL_ICON}"/>` +
    `</svg>`
  );
}

/** Build the square logo SVG string for a given background/icon color. */
export function squareSvg(bg: string, icon: string): string {
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" width="704" height="704" viewBox="0 0 704 704" fill="none">` +
    `<rect width="704" height="704" rx="0" fill="${bg}"/>` +
    `<path fill="${icon}" d="${SQUARE_ICON}"/>` +
    `</svg>`
  );
}
